let settingsData=null,learningEntries=[],pendingLearningUpload=null,learningPollTimer=null,libraryData={templates:[],profiles:[],examples:[],glossary:[]},dossierEntries=[],glossaryJobs=[],glossaryImportText='',glossaryImportPreview=null,glossaryColumnMapping={};
