function libraryError(error){const message=error?.message||'';const target=$('#workspace-error');if(target)target.textContent=message;}
function updateRecoveryInfo(recovery={}){const target=$('#storage-recovery-info');if(!target)return;let message=learningT('Lokale Wiederherstellungspunkte: {count}/{max} · maximal {size} GiB. Sie liegen auf demselben Datenträger und ersetzen keine externe Sicherung.').replace('{count}',String(recovery.count||0)).replace('{max}',String(recovery.maxPoints||7)).replace('{size}',String(Math.round((recovery.maxBytes||4294967296)/1073741824)));if(recovery.errorCode)message+=' '+learningT('Foliquo konnte keinen lokalen Wiederherstellungspunkt anlegen ({code}).').replace('{code}',String(recovery.errorCode));if(recovery.recoveredAt)message+=' '+learningT('Der Workspace wurde aus einem lokalen Wiederherstellungspunkt vom {date} wiederhergestellt.').replace('{date}',new Intl.DateTimeFormat(document.documentElement.lang||'en',{dateStyle:'medium'}).format(new Date(recovery.recoveredAt)));target.textContent=message;}
async function workspaceTask(task){libraryError(null);if($('#scan-dialog-error'))$('#scan-dialog-error').textContent='';if($('#storage-error'))$('#storage-error').textContent='';try{await task();}catch(error){libraryError(error);if($('#scan-dialog')?.open)$('#scan-dialog-error').textContent=error.message;else if($('#guide-storage-dialog')?.open&&$('#storage-error'))$('#storage-error').textContent=error.message;else toast(error.message);}}
async function loadLibrary(){if(!localRuntime||!csrf)return;try{const [settings,learning,library,dossiers,jobs]=await Promise.all([localRequest('/api/settings').then(r=>r.json()),localRequest('/api/learning').then(r=>r.json()),localRequest('/api/library').then(r=>r.json()),localRequest('/api/dossiers').then(r=>r.json()),localRequest('/api/jobs').then(r=>r.json())]);settingsData=settings;learningEntries=learning.entries||[];libraryData=library;libraryData.glossary||=[];dossierEntries=dossiers.dossiers||[];glossaryJobs=jobs.jobs||[];$('#retention-days').value=settings.settings.retentionDays;$('#api-budget-limit').value=settings.settings.apiBudgetUSDMonthly||0;$('#storage-info').textContent=`${settings.storage}. Aufträge werden ${settings.settings.retentionDays} Tage aufbewahrt.`;updateRecoveryInfo(library.recovery);populateTranslationContext();renderDossiers();renderLearning();ensureGlossaryUI();renderGlossary();clearTimeout(learningPollTimer);if(learningEntries.some(entry=>['queued','analyzing'].includes(entry.status)))learningPollTimer=setTimeout(()=>void loadLibrary(),2400);}catch(error){libraryError(error);}}
function contextSelection(id){try{return document.getElementById(id)?.value||localStorage.getItem(`foliquo.${id}`)||'';}catch{return document.getElementById(id)?.value||'';}}
