$('#learning-upload-start').onclick=()=>void workspaceTask(async()=>{if(!pendingLearningUpload)throw new Error('Bitte die Dateien erneut auswählen.');const request=pendingLearningUpload;$('#learning-upload-start').disabled=true;try{const response=await localRequest('/api/learning/upload',{files:request.files,provider:request.provider,model:request.model,confirmed:true});const result=await response.json();pendingLearningUpload=null;$('#learning-upload-preflight').hidden=true;$('#learning-status').textContent=learningT('Analyse gestartet. Neue Beobachtungen bleiben bis zu deiner Freigabe inaktiv.');await loadLibrary();}finally{$('#learning-upload-start').disabled=false;}});
$('#learning-file').onchange=event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;void workspaceTask(async()=>{const status=$('#learning-status'),button=$('#learning-upload-title');$('#learning-file').disabled=true;button.textContent=learningT('Übersicht wird vorbereitet …');try{if(!localRuntime||!csrf)throw new Error(learningT('Bitte die lokale Anwendung öffnen.'));if(!providerReady||!$('#model')?.value){window.openAISettings?.($('#learning-file'));throw new Error(learningT('Verbinde zuerst über KI im Header einen Modellanbieter und wähle ein Modell.'));}const requestFiles=await documentsForRequest(files),provider=activeProvider||'chatgpt',model=$('#model').value,response=await localRequest('/api/learning/inspect',{files:requestFiles,provider,model}),preflight=await response.json();pendingLearningUpload={files:requestFiles,provider,model};$('#learning-upload-summary').textContent=`${preflight.fileCount} ${learningT('Dateien')} · ${preflight.pages} ${learningT('Seiten')} · etwa ${preflight.analysisRequestsEstimate} ${learningT('Modellanfragen')} · ${provider} · ${model}`;$('#learning-upload-files').replaceChildren(...preflight.files.map(file=>safeNode('li',`${file.name} · ${(file.bytes/1048576).toFixed(1)} MiB`)));$('#learning-upload-content').textContent=preflight.content;$('#learning-upload-standard').textContent=preflight.standard;$('#learning-upload-preflight').hidden=false;status.textContent=learningT('Noch keine Dateien werden an den KI-Anbieter gesendet. Starte die Analyse erst nach Prüfung dieser Übersicht.');}finally{button.textContent=learningT('Fertige Übersetzungen hinzufügen');$('#learning-file').disabled=false;}});};
const retentionForm=$('#retention-form'),retentionPanel=document.createElement('section'),storageError=document.createElement('p');storageError.id='storage-error';storageError.className='error';storageError.setAttribute('role','alert');$('#storage-info').after(storageError);retentionPanel.className='retention-impact';retentionPanel.hidden=true;retentionPanel.setAttribute('aria-live','polite');retentionPanel.innerHTML='<p class="retention-impact-copy"></p><div class="retention-impact-actions"><button class="secondary retention-backup" type="button">Sicherung herunterladen</button><button class="primary retention-confirm" type="button">Aufbewahrung verkürzen</button><button class="text-button retention-cancel" type="button">Abbrechen</button></div>';retentionForm.after(retentionPanel);
function saveRetention(days,confirm=false,confirmedAffectedCount=null){return workspaceTask(async()=>{settingsData=await localRequest('/api/settings',{retentionDays:days,confirm,confirmedAffectedCount}).then(r=>r.json());$('#storage-info').textContent=`${settingsData.storage}. Aufträge werden ${settingsData.settings.retentionDays} Tage aufbewahrt.`;retentionPanel.hidden=true;$('#retention-days').value=days;await pollQueue();toast('Aufbewahrungsfrist gespeichert.');});}
$('#api-budget-form')?.addEventListener('submit',event=>{event.preventDefault();void workspaceTask(async()=>{const value=Number($('#api-budget-limit').value);if(!Number.isFinite(value)||value<0||value>10000||Math.round(value*100)!==value*100)throw new Error('Bitte ein Monatslimit zwischen 0 und 10.000 USD mit höchstens zwei Nachkommastellen angeben.');settingsData=await localRequest('/api/settings',{apiBudgetUSDMonthly:value}).then(r=>r.json());$('#api-budget-status').textContent=value===0?'Monatslimit deaktiviert.':'Lokales Monatslimit gespeichert.';await window.refreshProviderUsage?.();});});
retentionForm.onsubmit=event=>{event.preventDefault();void workspaceTask(async()=>{const days=Number($('#retention-days').value);if(!Number.isInteger(days)||days<1||days>365)throw new Error('Bitte eine Aufbewahrungsfrist zwischen 1 und 365 Tagen wählen.');if(days>=Number(settingsData?.settings?.retentionDays||30)){await saveRetention(days);return;}const result=await localRequest(`/api/settings/retention-impact?days=${encodeURIComponent(days)}`).then(r=>r.json()),impact=result.impact;if(!impact.affectedCount){await saveRetention(days);return;}const cutoff=new Intl.DateTimeFormat(document.documentElement.lang||'de',{dateStyle:'medium'}).format(new Date(impact.cutoff));const retentionCopy='{count} gespeicherte Aufträge werden ab {date} inklusive ihrer Ergebnisse entfernt. Laufende oder gerade bearbeitete Aufträge bleiben erhalten.';retentionPanel.querySelector('.retention-impact-copy').textContent=(window.TOCRI18n?.t(retentionCopy)||retentionCopy).replace('{count}',String(impact.affectedCount)).replace('{date}',cutoff);retentionPanel.hidden=false;retentionPanel.querySelector('.retention-confirm').onclick=()=>void saveRetention(days,true,impact.affectedCount);retentionPanel.querySelector('.retention-cancel').onclick=()=>{retentionPanel.hidden=true;$('#retention-days').value=settingsData.settings.retentionDays;};retentionPanel.querySelector('.retention-backup').onclick=()=>void downloadBackup();});};
async function downloadBackup(clearPassword=false){return workspaceTask(async()=>{let fileHandle=null;if(typeof window.showSaveFilePicker==='function'){try{fileHandle=await window.showSaveFilePicker({suggestedName:'foliquo-backup.enc',types:[{description:learningT('Verschlüsselte Foliquo-Sicherung'),accept:{'application/octet-stream':['.enc']}}]});}catch(error){if(error.name==='AbortError')return;throw error;}}const response=await localRequest('/api/backup',{passphrase:$('#backup-passphrase').value});if(fileHandle&&response.body){const writable=await fileHandle.createWritable();await response.body.pipeTo(writable);}else downloadBlob(await response.blob(),'foliquo-backup.enc');if(clearPassword)$('#backup-passphrase').value='';toast('Verschlüsselte Sicherung erstellt.');});}
function encodeBackupPassphrase(value){const bytes=new TextEncoder().encode(value);let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function restoreRawBackup(file,passphrase){let response;try{response=await fetch('/api/backup/restore',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-Foliquo-Csrf':csrf,'X-Foliquo-Backup-Passphrase':encodeBackupPassphrase(passphrase),'X-Foliquo-Backup-Confirm':'true'},body:file});}catch{throw new Error('Die lokale Verbindung ist unterbrochen. Bitte Foliquo neu laden.');}if(!response.ok){let data;try{data=await response.json()}catch{}throw new Error(data?.error||'Die Sicherung konnte nicht wiederhergestellt werden.');}return response;}
$('#backup-download').onclick=()=>void downloadBackup(true);
$('#backup-restore').onclick=()=>void workspaceTask(async()=>{const file=$('#backup-file').files[0];if(!file)throw new Error('Bitte eine Sicherung auswählen.');if(!confirm('Die Sicherung ersetzt die aktuellen privaten Daten. Vorher eine Sicherung herunterladen. Fortfahren?'))return;await restoreRawBackup(file,$('#backup-passphrase').value);location.reload();});
